UPDATE fact_conflicts c SET old_fact_id = #{to}
  WHERE c.status = 'open' AND c.old_fact_id = #{from}
    AND NOT EXISTS (SELECT 1 FROM fact_conflicts d
                     WHERE d.old_fact_id = #{to} AND d.new_fact_id = c.new_fact_id)

UPDATE fact_conflicts c SET new_fact_id = #{to}
  WHERE c.status = 'open' AND c.new_fact_id = #{from}
    AND NOT EXISTS (SELECT 1 FROM fact_conflicts d
                     WHERE d.new_fact_id = #{to} AND d.old_fact_id = c.old_fact_id)

