INSERT INTO typed_fact_sources (fact_id, statement_id)
 SELECT #{to}, statement_id FROM typed_fact_sources WHERE fact_id = #{from}
 ON CONFLICT DO NOTHING

INSERT INTO implied_fact_sources (fact_id, rule_id, statement_id, entity_id)
 SELECT #{to}, rule_id, statement_id, entity_id FROM implied_fact_sources WHERE fact_id = #{from}
 ON CONFLICT DO NOTHING

